  'be.c.agency.o1': { m: 'اعرض قائمة ساعاتك على المكتب واطلب التصحيح.', f: 'اعرضي قائمة ساعاتك على المكتب واطلبي التصحيح.', x: 'عرض قائمة الساعات على المكتب وطلب التصحيح.' }, // nieuw, nalezen // nagelezen AI ronde 3
